window.EXAM_CHAPTER_DATA["west_econ"]["00_导论"] = {"id":"00_导论","name":"导论","kps":[{"id":"KP01","name":"资源稀缺性与经济学研究对象","file":"教材笔记/06_西方经济学/00_导论/知识点/KP01_资源稀缺性与经济学研究对象.md","questions":[{"id":"west_econ_00_导论_KP01_1","num":"1","stem":"经济学之所以产生，其基本前提是（　）。","options":{"A":"政府对经济的干预","B":"资源的稀缺性与人类欲望的无限性","C":"商品交换的出现","D":"货币的发明"},"answer":"B"},{"id":"west_econ_00_导论_KP01_2","num":"2","stem":"下列关于\"稀缺\"的说法，正确的是（　）。","options":{"A":"稀缺就是商品价格太高、人们买不起","B":"只有穷人才面临稀缺，富人不稀缺","C":"相对人类无限欲望，资源总是有限的，这才是稀缺","D":"稀缺会随着经济发展完全消失"},"answer":"C"},{"id":"west_econ_00_导论_KP01_3","num":"3","stem":"任何社会都必须解决的三个基本经济问题不包括（　）。","options":{"A":"生产什么","B":"如何生产","C":"为谁生产","D":"股票如何定价"},"answer":"D"},{"id":"west_econ_00_导论_KP01_4","num":"4","stem":"\"短缺\"与\"稀缺\"的区别在于（　）。","options":{"A":"短缺是天然的，稀缺是人为的","B":"短缺会随价格上升而缓解，稀缺不会因涨价消失","C":"二者完全相同，可以混用","D":"稀缺只存在于计划经济"},"answer":"B"},{"id":"west_econ_00_导论_KP01_5","num":"5","stem":"下列属于\"免费物品\"、不构成稀缺资源的是（　）。","options":{"A":"城市自来水","B":"阳光下海滩上的空气（取之不尽、不影响他人）","C":"公园里的共享单车","D":"限量版球鞋"},"answer":"B"},{"id":"west_econ_00_导论_KP01_6","num":"6","stem":"（反向选择）下列说法错误的是（　）。","options":{"A":"稀缺是相对欲望而言资源有限","B":"贫穷是资源绝对数量少，与稀缺含义不同","C":"只要经济足够发达，稀缺就会消失","D":"不同社会用不同方式回答三个基本经济问题"},"answer":"C"},{"id":"west_econ_00_导论_KP01_7","num":"7","stem":"经济学家把\"研究社会如何管理稀缺资源\"定义为（　）。","options":{"A":"会计学","B":"经济学","C":"社会学","D":"政治学"},"answer":"B"},{"id":"west_econ_00_导论_KP01_8","num":"8","stem":"\"生产什么\"这一基本问题，在市场经济中主要由（　）决定。","options":{"A":"政府计划委员会","B":"消费者需求与价格信号（货币选票）","C":"外国厂商","D":"随机抽签"},"answer":"B"},{"id":"west_econ_00_导论_KP01_9","num":"9","stem":"（现象）疫情初期口罩被抢购一空、排长队，放开价格并扩产后恢复正常。这一现象说明（　）。","options":{"A":"口罩本来就稀缺","B":"当时的抢购属于\"短缺\"，可通过价格和供给增加缓解","C":"口罩永远供不应求","D":"口罩不是商品"},"answer":"B"}]},{"id":"KP02","name":"机会成本","file":"教材笔记/06_西方经济学/00_导论/知识点/KP02_机会成本.md","questions":[{"id":"west_econ_00_导论_KP02_1","num":"1","stem":"机会成本是指（　）。","options":{"A":"生产中实际支付的货币成本","B":"把资源用于某用途时所放弃的其他用途中最高的收益","C":"已经花出去收不回的钱","D":"会计账面上记录的全部成本"},"answer":"B"},{"id":"west_econ_00_导论_KP02_2","num":"2","stem":"某君辞职（年薪 10 万）用自有资金 20 万（原本可获利息 1 万）开店，会计成本（进货、房租）共 30 万。其开店的机会成本是（　）。","options":{"A":"30 万","B":"40 万","C":"41 万","D":"51 万"},"answer":"C"},{"id":"west_econ_00_导论_KP02_3","num":"3","stem":"关于沉没成本，下列说法正确的是（　）。","options":{"A":"它是未来决策应重点考虑的成本","B":"它是已经发生、无法收回的成本，理性决策应忽略","C":"它等于机会成本","D":"它随价格变化而变化"},"answer":"B"},{"id":"west_econ_00_导论_KP02_4","num":"4","stem":"已买的不可退电影票，电影很难看。理性的做法是（　）。","options":{"A":"既然票钱花了，硬着头皮看完","B":"忽略已付票款（沉没成本），及时离场去做更有价值的事","C":"等看完本想等的彩蛋","D":"把票转卖后再决定"},"answer":"B"},{"id":"west_econ_00_导论_KP02_5","num":"5","stem":"机会成本与会计成本的关系是（　）。","options":{"A":"机会成本 = 会计成本","B":"机会成本 = 会计成本 + 放弃的最高收益（隐性成本）","C":"会计成本 = 机会成本 + 隐性成本","D":"二者毫无关系"},"answer":"B"},{"id":"west_econ_00_导论_KP02_6","num":"6","stem":"一块地既可种粮食（净收益 8000 元），也可种菜（净收益 10000 元），还可建停车场（净收益 12000 元）。若选择种粮食，其机会成本是（　）。","options":{"A":"8000 元","B":"10000 元","C":"12000 元","D":"30000 元"},"answer":"C"},{"id":"west_econ_00_导论_KP02_7","num":"7","stem":"（反向选择）下列关于机会成本的说法，错误的是（　）。","options":{"A":"机会成本是放弃的最高收益，不是放弃收益的总和","B":"资源别无他用时，机会成本接近零","C":"机会成本就是已经花出去的钱","D":"自有资金的利息属于隐性成本，应计入机会成本"},"answer":"C"},{"id":"west_econ_00_导论_KP02_8","num":"8","stem":"上大学四年，学费 4 万、生活费 6 万、若不上学可工作挣 20 万。上大学的机会成本是（　）。","options":{"A":"4 万","B":"10 万","C":"24 万","D":"30 万"},"answer":"C"},{"id":"west_econ_00_导论_KP02_9","num":"9","stem":"（现象）大学生纠结\"考研还是直接工作\"，最容易被忽略的成本是（　）。","options":{"A":"考研报名费","B":"复习资料费","C":"读研期间放弃的工资收入（机会成本）","D":"考上后的学费"},"answer":"C"}]},{"id":"KP03","name":"实证分析与规范分析","file":"教材笔记/06_西方经济学/00_导论/知识点/KP03_实证分析与规范分析.md","questions":[{"id":"west_econ_00_导论_KP03_1","num":"1","stem":"下列属于实证分析命题的是（　）。","options":{"A":"政府应当提高最低工资","B":"最低工资提高 10%，低端失业率约上升 2%","C":"对高收入者征税是公平的","D":"收入分配应向劳动者倾斜"},"answer":"B"},{"id":"west_econ_00_导论_KP03_2","num":"2","stem":"下列属于规范分析命题的是（　）。","options":{"A":"汽油税每升提高 1 元，碳排放约下降 5%","B":"2023 年城镇居民人均可支配收入为 51821 元","C":"政府应当加大对基础教育的投入","D":"需求定律表明价格上升需求量下降"},"answer":"C"},{"id":"west_econ_00_导论_KP03_3","num":"3","stem":"区分实证分析与规范分析的关键是（　）。","options":{"A":"语言是否通俗易懂","B":"命题能否被数据证实或证伪、是否涉及价值判断","C":"是否使用数学模型","D":"由哪位经济学家提出"},"answer":"B"},{"id":"west_econ_00_导论_KP03_4","num":"4","stem":"\"地铁涨价后日均客流量下降 10 万人次，因此政府应当上调地铁票价。\"这句话（　）。","options":{"A":"全部是实证命题","B":"前半句是实证，后半句是规范","C":"全部是规范命题","D":"全部是理论推导，无所谓"},"answer":"B"},{"id":"west_econ_00_导论_KP03_5","num":"5","stem":"经济学家之间最难以通过数据调和的分歧，通常来自（　）。","options":{"A":"计算错误","B":"价值观与政策目标的不同（规范层面）","C":"统计数据误差","D":"对概念定义的理解"},"answer":"B"},{"id":"west_econ_00_导论_KP03_6","num":"6","stem":"（反向选择）下列说法错误的是（　）。","options":{"A":"实证分析回答\"是什么\"","B":"规范分析回答\"应该是什么\"","C":"实证命题一定正确，规范命题一定错误","D":"实证为规范提供事实基础"},"answer":"C"},{"id":"west_econ_00_导论_KP03_7","num":"7","stem":"\"个税起征点从 3500 元提高到 5000 元后，国家每年少征税约 3200 亿元。\"这一命题属于（　）。","options":{"A":"规范分析","B":"实证分析","C":"价值判断","D":"无法判断"},"answer":"B"},{"id":"west_econ_00_导论_KP03_8","num":"8","stem":"下列研究方法中，属于规范分析的是（　）。","options":{"A":"用回归模型估计价格与需求量的关系","B":"测算一项政策的财政成本","C":"评价一项政策是否符合社会公平目标","D":"统计某商品的市场份额"},"answer":"C"},{"id":"west_econ_00_导论_KP03_9","num":"9","stem":"（现象）看一份政策报告时，下列做法最科学的是（　）。","options":{"A":"把报告当成完全客观的事实","B":"先分清哪些是数据结论、哪些是政策建议，再分别评价","C":"只看结论不看依据","D":"认为带数字的话一定正确"},"answer":"B"}]},{"id":"KP04","name":"边际分析方法","file":"教材笔记/06_西方经济学/00_导论/知识点/KP04_边际分析方法.md","questions":[{"id":"west_econ_00_导论_KP04_1","num":"1","stem":"\"边际\"一词在经济学中指（　）。","options":{"A":"总量","B":"平均量","C":"一个变量再增加一单位所引起的另一变量的变化量（增量）","D":"最大值"},"answer":"C"},{"id":"west_econ_00_导论_KP04_2","num":"2","stem":"理性人进行\"是否再做一单位\"决策时，遵循的原则是（　）。","options":{"A":"平均收益 ≥ 平均成本就做","B":"边际收益 ≥ 边际成本就做","C":"总收益最大就做","D":"价格最高就做"},"answer":"B"},{"id":"west_econ_00_导论_KP04_3","num":"3","stem":"某奶茶店已售 100 杯，平均成本 2 元/杯。第 101 杯不需加班，多花料钱 1.8 元，顾客愿出 2.5 元。理性的接单决策是（　）。","options":{"A":"不接，因为平均成本 2 元太高","B":"接，因为边际收益 2.5 元 > 边际成本 1.8 元","C":"接不接都一样","D":"涨价到 3 元再接"},"answer":"B"},{"id":"west_econ_00_导论_KP04_4","num":"4","stem":"总效用达到最大时，边际效用（　）。","options":{"A":"最大","B":"等于零","C":"最小","D":"为负"},"answer":"B"},{"id":"west_econ_00_导论_KP04_5","num":"5","stem":"下列属于边际量的是（　）。","options":{"A":"某企业全年总产值","B":"某产品平均每件成本","C":"多雇佣一名工人新增的产量（边际产量）","D":"某城市总人口"},"answer":"C"},{"id":"west_econ_00_导论_KP04_6","num":"6","stem":"航空公司起飞前还有空位，以 300 元甩卖，而平均每座成本约 800 元。航司仍愿卖的原因是（　）。","options":{"A":"航司在做慈善","B":"多载一名乘客的边际成本（约一份餐 30 元）远低于 300 元票价","C":"800 元是虚假成本","D":"航司不懂平均成本"},"answer":"B"},{"id":"west_econ_00_导论_KP04_7","num":"7","stem":"（反向选择）关于边际量与平均量，下列说法错误的是（　）。","options":{"A":"边际量是增量，平均量是总量除以数量","B":"边际收益为零时总收益最大","C":"平均成本一定等于边际成本","D":"决策应看边际量而非平均量"},"answer":"C"},{"id":"west_econ_00_导论_KP04_8","num":"8","stem":"已经学了 3 小时，第 4 小时能多拿 5 分（价值 50 元），而这 1 小时打工可赚 30 元。理性决策是（　）。","options":{"A":"不学第 4 小时","B":"学第 4 小时，因为边际收益 50 元 ≥ 边际成本 30 元","C":"无所谓","D":"直接睡觉"},"answer":"B"},{"id":"west_econ_00_导论_KP04_9","num":"9","stem":"（现象）商家在景区卖纪念品标价高、却很少砍价成功，而飞机临期机票却大降价。二者共同体现的经济学原理是（　）。","options":{"A":"供求决定一切","B":"不同商品的边际成本不同，定价依据边际思维","C":"景区商家贪心","D":"飞机公司亏本"},"answer":"B"}]}]};
